#!/usr/bin/env python3
"""Audit the episode archive on main against the six friend branches.

Checks:
  1. frontmatter summary == the plain paragraph under the frontmatter
  2. every Friend-Message: 1 commit on the six branches appears exactly once
  3. no Source SHA is recorded twice across the archive
  4. spoken text recorded more than once across the archive
  5. every episode file has valid frontmatter (title/season/episode/status)
"""
import re
import subprocess
import sys
import collections

REPO = "/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]


def git(*args):
    return subprocess.run(
        ["git", "-C", REPO, *args], capture_output=True, text=True, check=True
    ).stdout


def main():
    files = sorted(
        p for p in git("ls-tree", "-r", "--name-only", "origin/main").split()
        if re.fullmatch(r"S\d+/E\d+\.md", p)
    )
    print(f"episode files on main: {len(files)}")

    summary_mismatch = []
    sha_sources = collections.defaultdict(list)   # sha -> [(file, line)]
    spoken = collections.defaultdict(list)        # text -> [(file, line)]
    episode_of_commit = {}                       # sha -> declared episode
    frontmatter_bad = []

    for path in files:
        text = git("show", f"origin/main:{path}")
        lines = text.split("\n")

        if not lines or lines[0].strip() != "---":
            frontmatter_bad.append((path, "no frontmatter"))
            continue
        try:
            end = lines.index("---", 1)
        except ValueError:
            frontmatter_bad.append((path, "unterminated frontmatter"))
            continue
        fm = "\n".join(lines[1:end])
        fm_summary = None
        for field in ("title", "summary", "season", "episode", "status"):
            m = re.search(rf"^{field}:\s*(.*)$", fm, re.M)
            if not m:
                frontmatter_bad.append((path, f"missing {field}"))
            elif field == "summary":
                fm_summary = m.group(1).strip().strip('"')
        m = re.search(r"^title:\s*(.*)$", fm, re.M)
        if m and not (m.group(1).strip().startswith('"')
                      and m.group(1).strip().endswith('"')):
            frontmatter_bad.append((path, "title not quoted"))

        body = lines[end + 1:]
        para = next((l for l in body if l.strip()), "")
        if fm_summary is not None and para.strip() != fm_summary.strip():
            summary_mismatch.append(path)

        cur = None
        for i, line in enumerate(body):
            m = re.match(r"^Source: friend/([a-z]+) @ ([0-9a-f]{40})$", line.strip())
            if m:
                sha_sources[m.group(2)].append((path, i))
                cur = m.group(1)
                continue
            m = re.match(r"^\*\*([A-Z][a-z]+)\*\* \((\S+)\)$", line.strip())
            if m:
                continue
            if cur and line.startswith(("Ross:", "Monica:", "Phoebe:", "Joey:",
                                        "Chandler:", "Rachel:")):
                spoken[line.strip()].append((path, i))
                cur = None

    print("\n--- frontmatter problems ---")
    for f, why in frontmatter_bad:
        print(f"  {f}: {why}")
    if not frontmatter_bad:
        print("  none")

    print("\n--- summary/paragraph mismatches ---")
    for f in summary_mismatch:
        print(f"  {f}")
    if not summary_mismatch:
        print("  none")

    # 3. duplicate Source records
    print("\n--- SHAs recorded more than once ---")
    dups = {s: v for s, v in sha_sources.items() if len(v) > 1}
    for s, v in sorted(dups.items()):
        print(f"  {s}")
        for f, i in v:
            print(f"      {f}")
    if not dups:
        print("  none")

    # 4. spoken text recorded more than once
    print("\n--- identical spoken text recorded more than once ---")
    for t, v in sorted(spoken.items()):
        if len(v) > 1:
            print(f"  {t[:70]}...")
            for f, i in v:
                print(f"      {f}")
    if not any(len(v) > 1 for v in spoken.values()):
        print("  none")

    # 5. coverage: every Friend-Message commit on the six branches
    print("\n--- coverage of Friend-Message commits ---")
    missing = []
    for br in BRANCHES:
        log = git("log", "--format=%H%x1f%s%x1f%B%x1e", f"origin/friend/{br}")
        for rec in log.split("\x1e"):
            rec = rec.strip("\n")
            if not rec:
                continue
            sha, subject, body = rec.split("\x1f", 2)
            if "Friend-Message: 1" not in body:
                continue
            m = re.search(r"^Episode:\s*(\S+)$", body, re.M)
            if not m:
                continue
            episode_of_commit[sha] = (br, m.group(1))
    for sha, (br, ep) in episode_of_commit.items():
        if sha not in sha_sources:
            missing.append((sha, br, ep))
    if missing:
        print(f"  {len(missing)} committed utterance(s) never recorded:")
        for sha, br, ep in sorted(missing, key=lambda x: x[2]):
            print(f"    {sha} {ep:8} friend/{br}")
    else:
        print("  all recorded")

    # 6. recorded in the wrong episode
    print("\n--- recorded under a different episode than declared ---")
    misplaced = []
    for sha, v in sha_sources.items():
        if sha in episode_of_commit:
            br, ep = episode_of_commit[sha]
            if v[0][0] != f"{ep.split('/')[0]}/{ep.split('/')[1]}.md":
                misplaced.append((sha, ep, v[0][0]))
    for sha, ep, f in sorted(misplaced):
        print(f"  {sha} declared {ep}, recorded in {f}")
    if not misplaced:
        print("  none")


if __name__ == "__main__":
    sys.exit(main())

