#!/usr/bin/env python3
"""For each episode file, list which of the six friends actually committed a
Friend-Message for that episode, and compare with who is recorded in the file.
A friend absent from the file but present on the branch = a lost utterance.
"""
import re
import subprocess
import collections

REPO = "/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
FRIENDS = ("Rachel", "Monica", "Phoebe", "Joey", "Chandler", "Ross")


def git(*args):
    return subprocess.run(["git", "-C", REPO, *args],
                          capture_output=True, text=True).stdout


def main():
    files = sorted(p for p in git("ls-tree", "-r", "--name-only", "origin/main").split()
                   if re.fullmatch(r"S\d+/E\d+\.md", p))

    # every committed utterance: sha -> (episode, branch)
    committed = collections.defaultdict(list)
    for br in FRIENDS:
        log = git("log", "--format=%H%x1f%B%x1e", f"origin/friend/{br.lower()}")
        for rec in log.split("\x1e"):
            rec = rec.strip("\n")
            if not rec:
                continue
            sha, body = rec.split("\x1f", 1)
            if "Friend-Message: 1" not in body:
                continue
            m = re.search(r"^Episode:\s*(\S+)$", body, re.M)
            if m:
                committed[m.group(1)].append((sha, br))

    lost_total = 0
    for path in files:
        ep = path[:-3]  # S05/E16
        body = git("show", f"origin/main:{path}")
        recorded_shas = set(re.findall(r"^Source: friend/\w+ @ ([0-9a-f]{40})", body, re.M))
        recorded_speakers = set(re.findall(r"^\*\*(\w+)\*\*", body, re.M))

        branch_shas = {sha for sha, _ in committed.get(ep, [])}
        branch_speakers = {br for _, br in committed.get(ep, [])}

        missing_shas = branch_shas - recorded_shas
        # a speaker counts as present if recorded at all
        absent_speakers = branch_speakers - recorded_speakers

        if missing_shas or absent_speakers:
            lost = len(missing_shas)
            lost_total += lost
            print(f"{path}: {lost} unrecorded utterance(s), "
                  f"speakers on branch but absent from file: "
                  f"{', '.join(sorted(absent_speakers)) or 'none'}")
    print(f"\ntotal unrecorded utterances across the archive: {lost_total}")


if __name__ == "__main__":
    main()

